insert into public.suporte_artigos (slug,titulo,resumo,categoria,passos,dica,destino,tags,publicado,atualizado_em) values
('entrar-na-conta','Entrar na sua conta','Use o mesmo e-mail e a mesma forma de entrada escolhidos no cadastro.','conta','["Abra a tela de entrada. Se você se cadastrou pelo Google, escolha entrar com o Google e selecione a mesma conta.","Se usa e-mail e senha, confira o endereço antes de tentar novamente. Para redefinir a senha, use Esqueceu a senha na tela de entrada.","Procure a mensagem de recuperação também em spam. Use o link mais recente recebido."]','Não consegue entrar? Abra um pedido em Ajuda → Problema de acesso. Nunca envie sua senha ou código de verificação ao suporte.','/conta','login senha acesso google cadastro email recuperar',true,'2026-09-08T19:00:00Z'),
('saldo-e-creditos','Consultar saldo e uso de créditos','Seu saldo aparece próximo ao perfil. As operações pagas informam o custo antes da confirmação.','conta','["Abra o saldo de créditos junto ao perfil ou acesse Conta → Créditos.","Consulte o histórico para identificar o uso registrado.","Se uma operação não terminou como esperado, informe ao suporte o horário e a funcionalidade. Não repita vários envios para tentar corrigir."]','O suporte não cobra créditos. Limites de uso da IA de ajuda protegem a disponibilidade do serviço e não alteram seu saldo.','/conta/creditos','saldo moeda custo consumo creditos enriquecimento mentoria',true,'2026-09-08T19:00:00Z'),
('conectar-google-agenda','Conectar o Google Agenda','Conecte a agenda da conta que deve organizar e enviar os convites das suas reuniões.','reunioes','["Abra Minha conta e localize a integração com o Google Agenda.","Escolha conectar e, na tela do Google, selecione a conta e revise as permissões solicitadas.","Ao voltar ao Subido, confira se a integração aparece conectada antes de agendar uma reunião."]','Se o Google mostrar um bloqueio ou aviso de verificação, não considere a conexão concluída. Envie o texto ou um print ao suporte, sem códigos ou tokens. A aprovação do aplicativo pelo Google é independente do seu cadastro no Subido.','/conta','calendar calendario agenda oauth autorizacao conectar sincronizar google',true,'2026-09-08T19:00:00Z'),
('agendar-reuniao','Agendar uma reunião com o cliente','A reunião fica ligada ao seu trabalho e o convite usa o link público da sala do Subido.','reunioes','["Com o Google Agenda conectado, abra Reuniões ou a ficha do cliente em Vendas e escolha agendar.","Confira data, horário, fuso e e-mail dos participantes antes de confirmar.","Depois de agendar, confira o estado do convite. Copie o link da sala se precisar compartilhá-lo por outro canal."]','Reunião salva e convite enviado são estados diferentes. Se o envio falhar, confira a conexão da agenda e o aviso da reunião antes de criar outra.','/reunioes','call convite invite sala horario link reuniao agendar fuso',true,'2026-09-08T19:00:00Z'),
('enriquecer-oportunidade','Enriquecer uma oportunidade','O enriquecimento usa as informações já cadastradas na ficha para pesquisar a empresa e ajudar a preparar a abordagem.','vendas','["Abra Vendas e selecione a ficha do cliente. Confira os dados de identificação e o site, quando disponível.","Escolha Enriquecer oportunidade e revise o custo em créditos antes de confirmar.","Acompanhe o processamento na ficha. Ao terminar, revise os dados, as fontes e as sugestões para a conversa."]','Hipóteses de projeto precisam ser validadas com o cliente. A pesquisa não garante encontrar todos os contatos ou decisores. Se travar, informe a ficha ao suporte sem iniciar várias tentativas.','/vendas','enriquecimento lead pesquisar empresa dados loading travou',true,'2026-09-08T19:00:00Z'),
('criar-proposta-sem-reuniao','Criar uma proposta sem reunião','Você pode preparar uma proposta a partir do que combinou por WhatsApp, pessoalmente ou em outro canal. Uma reunião na plataforma não é obrigatória.','vendas','["Abra a ficha do cliente em Vendas e escolha Criar proposta, ou comece pela seção Propostas.","Preencha o que foi combinado: objetivo, escopo, prazo e investimento.","Revise a prévia antes de compartilhar. Rascunhos e propostas enviadas ficam separados."]','A proposta deve refletir o que você realmente consegue entregar. Revise textos e valores antes do envio.','/propostas','proposta rascunho enviada whatsapp offline sem call editar previa',true,'2026-09-08T19:00:00Z'),
('organizar-vendas','Organizar oportunidades no quadro de vendas','Mantenha em Vendas apenas as oportunidades em que pretende trabalhar.','vendas','["Abra Vendas e escolha uma oportunidade para consultar sua ficha.","Registre a próxima ação e mova a oportunidade quando a negociação mudar de etapa.","Use as ações da ficha ou do cartão para encerrar oportunidades que não seguirão e registrar o resultado da venda."]','Uma empresa encontrada em Prospecção ainda não representa uma venda. Leve para Vendas os contatos que vai trabalhar.','/vendas','kanban crm ganho perdido arquivar desclassificar etapa lead',true,'2026-09-08T19:00:00Z'),
('aprender-e-implementar','Aprender a implementar um projeto','Cada projeto reúne aprendizado, implementação e os pré-requisitos e materiais necessários.','projetos','["Abra Projetos e escolha o serviço que quer aprender a entregar.","Comece pelo conteúdo de aprendizado e confira os pré-requisitos antes da implementação.","Na implementação, avance pelas fases Entender, Preparar, Construir, Validar e Entregar. Consulte o material do passo em foco quando precisar."]','A plataforma orienta e organiza o trabalho. Você é responsável por implementar, testar e entregar o serviço ao cliente.','/solucoes','nina curso projeto tutorial materiais requisitos construir aprender',true,'2026-09-08T19:00:00Z'),
('entrega-pontual-recorrente','Concluir uma entrega ou manter o acompanhamento','Projetos pontuais podem ser concluídos. Serviços recorrentes continuam com acompanhamento após a entrega inicial.','projetos','["Abra Entregas e entre na sala do projeto do cliente.","Revise tarefas e materiais. Quando usar o portal do cliente, confira as aprovações e pedidos de ajuste.","Na gestão do serviço, escolha a conclusão pontual ou o acompanhamento recorrente, de acordo com o que foi contratado."]','Marcar uma tarefa como feita não substitui o aceite do cliente. Recorrência não gera cobrança automática nesta configuração.','/entregas','recorrente concluido entregue aceite tarefa suporte projeto finalizar',true,'2026-09-08T19:00:00Z'),
('compartilhar-certificado','Compartilhar um certificado','Certificados disponíveis na sua conta têm uma página pública para conferir e compartilhar a conclusão.','projetos','["Abra Certificados e selecione o certificado desejado.","Confira nome e conteúdo antes de baixar ou compartilhar.","Use a opção de LinkedIn ou copie o link público. No LinkedIn, revise os campos antes de publicar."]','Se o certificado não apareceu após a conclusão, confira os requisitos do conteúdo. Informe ao suporte o nome da formação ou projeto.','/certificados','certificado linkedin diploma nome download compartilhar conclusao',true,'2026-09-08T19:00:00Z'),
('enviar-arquivos-sobral','Enviar arquivos e áudio ao Sobral AI','Use anexos para dar mais contexto à sua pergunta, como um documento, uma imagem ou um áudio.','ia','["Abra Sobral AI e inicie uma conversa ou escolha uma do histórico.","Use a opção de arquivo ou gravação. Confira se o envio terminou antes de mandar a pergunta.","Diga o que precisa que seja analisado. Se ocorrer um erro, confira o formato e o limite exibidos na tela."]','Envie apenas materiais que você tem autorização para compartilhar. Nunca inclua senhas, tokens ou dados de clientes que não sejam necessários.','/consultor','audio imagem pdf documento anexo upload gravar chat sobral ia',true,'2026-09-08T19:00:00Z'),
('pagina-ou-operacao-com-erro','Uma página ou operação não terminou','Antes de repetir a ação, confira se o resultado já foi salvo. Isso ajuda a evitar duplicações.','outros','["Anote a funcionalidade e o horário aproximado. Se houver aviso, copie o texto ou faça uma captura.","Se você estava editando, preserve o texto ainda não salvo antes de atualizar a página.","Abra Pedir ajuda e descreva o que tentou fazer e o que apareceu. Compartilhe somente o contexto necessário."]','Nunca envie dados de acesso. O suporte pode investigar o problema sem pedir sua senha.','/suporte','erro travado loading carregando branco lento falha pagina bug',true,'2026-09-08T19:00:00Z');
